   """Issue #2257: delete each preview of a set that ships from the files given."""
   import re, sys

   SHIPPED = r'(?:jackioh_engine::)?SetName::(?:Meditative|MeditativePlus|Stinkyscape)'
   CALL = re.compile(r'^\s*let _\w* = (?:jackioh_engine::testkit::)?preview_sets\(&\[' + SHIPPED + r'\]\);\s*$')
   OPEN_CALL = re.compile(r'^\s*let _\w* = open\(\);\s*$')
   OPEN_FN = re.compile(r'^\s*fn open\(\) -> PreviewGuard \{\s*$')

   for path in sys.argv[1:]:
       lines = open(path, encoding='utf-8').read().split('\n')
       out, i = [], 0
       while i < len(lines):
           if OPEN_FN.match(lines[i]):
